inputs = ['zxjyyf', 'jzwbux', 'cbkhuk', 'fuzie', 'yyjai']
outputs = ['zyzcjyyf', 'jzwcyzc', 'ccacahuca', 'fuzie', 'yyjai']

print("Length analysis:")
for i in range(len(inputs)):
    print(f"'{inputs[i]}' (len={len(inputs[i])}) -> '{outputs[i]}' (len={len(outputs[i])})")

print("\nDetailed character analysis:")
for i in range(len(inputs)):
    inp = inputs[i]
    outp = outputs[i]
    print(f"'{inp}' -> '{outp}'")
    # Show differences
    min_len = min(len(inp), len(outp))
    for j in range(min_len):
        if inp[j] != outp[j]:
            print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
    if len(inp) != len(outp):
        if len(inp) < len(outp):
            print(f"  Extra chars in output: {outp[len(inp):]}")
        else:
            print(f"  Missing chars in output: {inp[len(outp):]}")
    print()

